const dotWide=(a,b)=>a.reduce((sum,x,i)=>sum+x*b[i],0n);
const monomials=[[0,0],[1,1],[2,2],[0,1],[0,2],[1,2]];
const pointRows=P.map(p=>monomials.map(([i,j])=>p[i]*p[j]));
const jets=G.map(([u,v])=>monomials.map(([i,j])=>P[u][i]*P[v][j]+P[u][j]*P[v][i]));
const endpointBits=P.map((_,i)=>G.filter(([u])=>u===i).reduce((s,[,,b])=>s|b,0n));
const chamberRows=[[0n,0n,34n,0n,1n,0n],[0n,0n,31n,0n,1n,17n]];

function positiveCombination(a,b,k) {
  const ap=-b.r[k],bp=a.r[k];
  const weights=new Map();
  for(const [m,w] of a.weights) weights.set(m,ap*w);
  for(const [m,w] of b.weights) weights.set(m,(weights.get(m)??0n)+bp*w);
  const row=a.r.map((v,i)=>ap*v+bp*b.r[i]).filter((_,i)=>i!==k);
  return {r:row,strict:a.strict||b.strict,weights};
}

function eliminate(raw,dimension) {
  let rows=raw.map((x,i)=>({...x,weights:new Map([[i,1n]])}));
  for(let d=dimension;d>=0;d--) {
    const unique=new Map();
    for(const row of rows) {
      const {r,strict,weights}=row;
      if(!r.slice(1).some(Boolean)) {
        if(r[0]<0n || strict&&!r[0]) return weights;
        continue;
      }
      const key=norm(r).join();
      if(!unique.has(key)||strict) unique.set(key,row);
    }
    if(!d) break;
    rows=[...unique.values()];
    const opts=Array.from({length:d},(_,i)=>{
      const k=i+1;
      const pos=rows.filter(x=>x.r[k]>0n),neg=rows.filter(x=>x.r[k]<0n);
      return {k,pos,neg,cost:pos.length*neg.length};
    }).sort((a,b)=>a.cost-b.cost);
    const {k,pos,neg}=opts[0];
    const next=rows.filter(x=>!x.r[k]).map(x=>({...x,r:x.r.filter((_,i)=>i!==k)}));
    for(const a of pos) for(const b of neg) next.push(positiveCombination(a,b,k));
    rows=next;
  }
  return null;
}

function checkCertificate(rows,weights,dimension) {
  if([...weights.values()].some(w=>w<=0n)) throw Error("nonpositive combination weight");
  const sum=Array.from({length:dimension+1},(_,j)=>
    [...weights].reduce((s,[i,w])=>s+w*rows[i].r[j],0n));
  const strict=[...weights].some(([i])=>rows[i].strict);
  if(sum.slice(1).some(Boolean) || sum[0]>0n || !sum[0]&&!strict) throw Error("invalid contradiction");
  return {sum:sum.map(String),strict,terms:[...weights].map(([i,w])=>({weight:String(w),
    source:rows[i].source,row:rows[i].r.map(String),strict:rows[i].strict}))};
}

function kernel(equations) {
  let basis=Array.from({length:6},(_,i)=>Array.from({length:6},(_,j)=>i===j?1n:0n));
  for(const row of equations) {
    const values=basis.map(x=>dotWide(row,x));
    const pivot=values.findIndex(Boolean);
    if(pivot>=0) basis=basis.flatMap((x,i)=>i===pivot?[]:[
      norm(x.map((y,j)=>values[pivot]*y-values[i]*basis[pivot][j]))
    ]);
  }
  return basis;
}

const results=[];
for(const {a:aa,b:bb,pointsPositive,pointsNegative,zeros} of upstream.final) {
  const a=BigInt("0x"+aa),b=BigInt("0x"+bb);
  const Pp=BigInt("0x"+pointsPositive),Pn=BigInt("0x"+pointsNegative);
  const signAt=P.map((_,i)=>endpointBits[i]&Pp?1n:endpointBits[i]&Pn?-1n:0n);
  if(signAt.map((s,i)=>s?-1:i).filter(i=>i>=0).join()!==zeros.join()) throw Error("zero provenance");
  const meta={zeros,mask:aa+","+bb};
  const basis=kernel(zeros.map(i=>pointRows[i]));
  const pivot=basis.findIndex(v=>v[2]);
  if(pivot<0) {
    results.push({...meta,feasible:false,reason:"c=0 forced"});
    continue;
  }
  const origin=scale(basis[pivot],BigInt(sg(basis[pivot][2])));
  const dirs=basis.filter((_,i)=>i!==pivot).map(v=>norm(v.map((y,j)=>origin[2]*y-v[2]*origin[j])));
  const chart=[origin,...dirs];
  const rows=[];
  const add=(row,strict,source)=>rows.push({r:chart.map(x=>dotWide(x,row)),strict,source});
  chamberRows.forEach((row,i)=>add(row,false,"domain "+i));
  add([0n,0n,-68n,0n,-3n,0n],true,"domain 2");
  for(let i=0;i<P.length;i++) if(signAt[i]) add(scale(pointRows[i],signAt[i]),true,"endpoint "+i);
  for(let i=0;i<G.length;i++) {
    const [u,v,bit]=G[i];
    if(signAt[u]) continue;
    const want=a&bit?1n:b&bit?-1n:0n;
    if(!want) throw Error("missing desired sign");
    add(scale(jets[i],want),signAt[v]!==want,"germ "+i);
  }
  const dimension=dirs.length;
  const conflict=eliminate(rows,dimension);
  const certificate=conflict?checkCertificate(rows,conflict,dimension):null;
  results.push({...meta,dimension,feasible:!certificate,certificate});
}
return {results};
